(()=>{'use strict';const URL='player-data/photo-map.json?v=20260818-s2-mvp-photos-v1';let map=null,promise=null;const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'');const valid=v=>{const s=String(v||'').trim();return s&&s!=='silhueta.webp'?s:''};function load(){if(map)return Promise.resolve(map);if(promise)return promise;promise=fetch(URL,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject(new Error('Mapa de fotos indisponível'))).then(d=>map=d&&d.photos||{}).catch(()=>map={});return promise}function resolve(name,explicit=''){const direct=valid(explicit);if(direct)return direct;const key=norm(name);return valid(map&&map[key])||'silhueta.webp'}window.cffLoadPlayerPhotoMap=load;window.cffResolvePlayerPhoto=resolve;window.cffNormalizePlayerPhotoKey=norm;})();